import { LatheGeometry, Vector2 } from "three";

/**
 * Build a parametric vase via LatheGeometry over a sine-shaped profile.
 *
 * The profile radius at height t in [0, 1] is:
 *   r(t) = maxRadius * (base + amplitude * sin(pi * t^curvature-ish))
 * shaped so the vase bulges in the middle and narrows toward top/bottom.
 */
export function buildVase({ height = 2, maxRadius = 1, curvature = 1, radialSegments = 32 } = {}) {
  if (!(height > 0)) throw new RangeError("height must be > 0");
  if (!(maxRadius >= 0)) throw new RangeError("maxRadius must be >= 0");
  if (!(curvature > 0)) throw new RangeError("curvature must be > 0");

  const points = [];
  const profileSegments = 64;
  for (let i = 0; i <= profileSegments; i++) {
    const y = (i / profileSegments) * height;
    // Sine-shaped profile: bulge at mid-height, tapering to the ends.
    const r =
      maxRadius * (0.35 + 0.65 * Math.sin(Math.PI * Math.pow(i / profileSegments, curvature)));
    points.push(new Vector2(Math.max(r, 1e-4), y));
  }

  return new LatheGeometry(points, radialSegments);
}

