// Minimal Node polyfills for three's GLTFExporter, which (even in text/JSON
// mode) may touch FileReader and Blob. Provide just enough for the exporter
// to run under node:fs-based workflows.
import { Blob as NodeBlob } from "node:buffer";

if (typeof globalThis.Blob !== "function") {
  globalThis.Blob = class Blob extends NodeBlob {};
}

if (typeof globalThis.FileReader !== "function") {
  // readAsText is the only path exercised for non-binary exports.
  globalThis.FileReader = class FileReader {
    readAsText(blob) {
      Promise.resolve()
        .then(() => blob.text())
        .then(
          (text) => {
            this.result = text;
            this.readyState = 2;
            this.onloadend?.({ target: this });
            this.onload?.({ target: this });
          },
          (error) => {
            this.error = error;
            this.onerror?.({ target: this });
          }
        );
    }
    readAsArrayBuffer(blob) {
      blob
        .arrayBuffer()
        .then(
          (buf) => {
            this.result = buf;
            this.readyState = 2;
            this.onloadend?.({ target: this });
            this.onload?.({ target: this });
          },
          (error) => {
            this.error = error;
            this.onerror?.({ target: this });
          }
        );
    }
    readAsDataURL() {}
  };
}

import { GLTFExporter } from "three/examples/jsm/exporters/GLTFExporter.js";

/**
 * Export a THREE.Object3D to a glTF JSON object (binary: false).
 * @returns {Promise<object>} parsed glTF JSON
 */
export function vaseToGltf(vase) {
  return new Promise((resolve, reject) => {
    new GLTFExporter().parse(vase, resolve, reject, { binary: false });
  });
}

