import { describe, it, expect } from "vitest";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import path from "node:path";
import { buildVase } from "../src/vase.js";
import { vaseToGltf } from "../src/export.js";

const OUT_DIR = path.resolve("out");
const OUT_FILE = path.join(OUT_DIR, "vase.gltf");

const params = { height: 2.5, maxRadius: 0.8, curvature: 1.4, radialSegments: 48 };

async function exportVase() {
  const vase = buildVase(params);
  const json = await vaseToGltf(vase);
  return { vase, json };
}

describe("vaseToGltf", () => {
  it("produces glTF 2.0 asset", async () => {
    const { json } = await exportVase();
    expect(json.asset.version).toBe("2.0");
  });

  it("contains exactly one mesh with one primitive", async () => {
    const { json } = await exportVase();
    expect(json.meshes).toHaveLength(1);
    expect(json.meshes[0].primitives).toHaveLength(1);
  });

  it("POSITION accessor count matches geometry position count", async () => {
    const { vase, json } = await exportVase();
    const prim = json.meshes[0].primitives[0];
    const accessor = json.accessors[prim.attributes.POSITION];
    expect(accessor.count).toBe(vase.geometry.attributes.position.count);
  });

  it("POSITION accessor min/max bound the stated height within 1e-3", async () => {
    const { json } = await exportVase();
    const prim = json.meshes[0].primitives[0];
    const accessor = json.accessors[prim.attributes.POSITION];
    // Y is index 1; profile spans y in [0, height].
    expect(accessor.min[1]).toBeGreaterThanOrEqual(0 - 1e-3);
    expect(accessor.max[1]).toBeLessThanOrEqual(params.height + 1e-3);
    // And the bounds actually reach the full height (not degenerate).
    expect(Math.abs(accessor.max[1] - params.height)).toBeLessThan(1e-3);
  });

  it("buffers[0].byteLength > 0", async () => {
    const { json } = await exportVase();
    expect(json.buffers[0].byteLength).toBeGreaterThan(0);
  });

  it("writes out/vase.gltf that re-parses as JSON", async () => {
    const { json } = await exportVase();
    await mkdir(OUT_DIR, { recursive: true });
    await writeFile(OUT_FILE, JSON.stringify(json, null, 2), "utf8");
    const reparsed = JSON.parse(await readFile(OUT_FILE, "utf8"));
    expect(reparsed.asset.version).toBe("2.0");
    expect(reparsed.meshes).toHaveLength(1);
  });
});

